CREATE TABLE IF NOT EXISTS review_reminders (reminder_id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES users(owner_id) ON DELETE CASCADE, research_request_id UUID REFERENCES research_requests(request_id) ON DELETE CASCADE, due_at TIMESTAMPTZ NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','acknowledged','snoozed','dismissed')), note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
